CREATE TABLE funcionarios (id BIGSERIAL PRIMARY KEY, nome VARCHAR(150) NOT NULL, cargo VARCHAR(100) NOT NULL, email VARCHAR(180) NOT NULL UNIQUE, telefone VARCHAR(30), status VARCHAR(30) NOT NULL DEFAULT 'Ativo', criado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, atualizado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE obras (id BIGSERIAL PRIMARY KEY, nome VARCHAR(180) NOT NULL, cliente VARCHAR(150) NOT NULL, cidade VARCHAR(150) NOT NULL, inicio DATE NOT NULL, status VARCHAR(40) NOT NULL, criado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, atualizado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE obra_responsaveis (obra_id BIGINT NOT NULL REFERENCES obras(id) ON DELETE CASCADE, funcionario_id BIGINT NOT NULL REFERENCES funcionarios(id), PRIMARY KEY (obra_id, funcionario_id));
CREATE TABLE equipamentos (id BIGSERIAL PRIMARY KEY, tipo VARCHAR(40) NOT NULL, modelo VARCHAR(180) NOT NULL, serie VARCHAR(120) NOT NULL UNIQUE, status VARCHAR(40) NOT NULL, obra_id BIGINT REFERENCES obras(id), tecnico_id BIGINT REFERENCES funcionarios(id), data_entrada DATE, data_saida DATE, criado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, atualizado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE solicitacoes (id BIGSERIAL PRIMARY KEY, tipo VARCHAR(40) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'Pendente', tecnico_id BIGINT NOT NULL REFERENCES funcionarios(id), obra_origem_id BIGINT REFERENCES obras(id), obra_destino_id BIGINT REFERENCES obras(id), data_solicitacao DATE NOT NULL, data_decisao DATE, observacao TEXT, criado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, atualizado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE materiais_solicitados (id BIGSERIAL PRIMARY KEY, solicitacao_id BIGINT NOT NULL REFERENCES solicitacoes(id) ON DELETE CASCADE, nome VARCHAR(180) NOT NULL, quantidade INTEGER NOT NULL CHECK (quantidade > 0), identificacao VARCHAR(120));
CREATE TABLE movimentacoes (id BIGSERIAL PRIMARY KEY, equipamento_id BIGINT NOT NULL REFERENCES equipamentos(id), solicitacao_id BIGINT REFERENCES solicitacoes(id), obra_origem_id BIGINT REFERENCES obras(id), obra_destino_id BIGINT REFERENCES obras(id), tecnico_id BIGINT REFERENCES funcionarios(id), status VARCHAR(40) NOT NULL, data_movimentacao DATE NOT NULL, ativa BOOLEAN NOT NULL DEFAULT TRUE, cancelada_em TIMESTAMPTZ, criado_em TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_movimentacao_solicitacao_equipamento UNIQUE (solicitacao_id, equipamento_id));
CREATE INDEX idx_equipamentos_obra ON equipamentos(obra_id);
CREATE INDEX idx_equipamentos_status ON equipamentos(status);
CREATE INDEX idx_solicitacoes_status ON solicitacoes(status);
CREATE INDEX idx_movimentacoes_equipamento ON movimentacoes(equipamento_id);
CREATE INDEX idx_movimentacoes_obras ON movimentacoes(obra_origem_id, obra_destino_id);
